  static Future<void> _simulateLatency(int latencyMs, int jitterMs) async {
    final totalMs =
        latencyMs + (jitterMs > 0 ? _random.nextInt(jitterMs + 1) : 0);
    if (totalMs > 0) {
      await Future.delayed(Duration(milliseconds: totalMs));
    }
  }

  static bool _shouldSimulateError(double errorRate) =>
      errorRate > 0 && _random.nextDouble() < errorRate;

  static ApiCallResponse _response(
    String body,
    int statusCode,
    Map<String, String> headers,
  ) =>
      ApiCallResponse(
        _tryDecode(body),
        {..._jsonHeaders, ...headers},
        statusCode,
      );

  static dynamic _tryDecode(String body) {
    if (body.isEmpty) {
      return null;
    }
    try {
      return jsonDecode(body);
    } catch (_) {
      return body;
    }
  }

  static Map<String, dynamic> _decodeJsonObject(String? body) {
    if (body == null || body.isEmpty) {
      return {};
    }
    try {
      final decoded = jsonDecode(body);
      return decoded is Map ? Map<String, dynamic>.from(decoded) : {};
    } catch (_) {
      return {};
    }
  }

  /// Wraps operation results into the configured response shape. Tokens:
  /// <rows>, <row>, <totalCount>.
  static dynamic _applyResponseTemplate(
    String template, {
    dynamic rows,
    dynamic row,
    int? totalCount,
  }) {
    final encoded = template
        .replaceAll('<rows>', jsonEncode(rows ?? []))
        .replaceAll('<row>', jsonEncode(row))
        .replaceAll('<totalCount>', jsonEncode(totalCount ?? 0));
    return _tryDecode(encoded);
  }

  static int? _toInt(dynamic value) =>
      value is int ? value : int.tryParse('${value ?? ''}');

  /// Converts a 1-based page number into a row offset.
  static int? _pageOffset(int? page, int? limit) =>
      page == null ? null : (page - 1) * (limit ?? 20);
